# Regenerates app/src/lib/f75themes.ts from the configuration table of f75.sc (one row per colour theme).
# Run from the repo root: python docs/keyboard-model/themes.py
import json
import zipfile

doc = json.loads(zipfile.ZipFile("docs/keyboard-model/f75.sc").read("document.json"))
cols = doc["configs"]["columns"]
out = [
    "// Generated by docs/keyboard-model/themes.py from the configuration table of f75.sc. Do not edit.",
    "// colors: sRGB per body name of f75.glb. side: legends on the cap front (LegendSide*) instead of the top.",
    "export type Theme = { name: string; side: boolean; shine: boolean; colors: Record<string, string> };",
    "export const THEMES: Theme[] = [",
]
for row in doc["configs"]["rows"]:
    colors = {}
    for col, cell in zip(cols, row["cells"]):
        if "appearance" in col and cell:
            colors[col["appearance"]] = "#" + "".join(f"{c:02x}" for c in json.loads(cell)["color"])
    name = row["name"]
    theme = {"name": name, "side": "Side-Printed" in name, "shine": "Shine-Through" in name, "colors": colors}
    out.append(f"  {json.dumps(theme, ensure_ascii=False)},")
out.append("];")
open("app/src/lib/f75themes.ts", "w", encoding="utf-8", newline="\n").write("\n".join(out) + "\n")
